import { loadCanonicalComponentContracts } from "./canonical-component-contracts.mjs";
import { createFrameworkGenerationModel } from "./framework-generation.mjs";

export const VUE_TYPED_CATALOG_ARTIFACT_PATH =
  "packages/ui-vue/src/generated/typed-catalog.generated.ts";
export const VUE_TYPE_GENERATION_TASK = "MFD-1307";

const GENERATED_HEADER = `/**
 * @generated by scripts/vue-type-generation.mjs
 * Source: docs/metadata/component-contracts.json
 * DO NOT EDIT. Regenerate with: npm run generate:framework-artifacts
 */`;

function compareText(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function assert(condition, message) {
  if (!condition) throw new Error(`Vue type generation: ${message}`);
}

function propertyName(name) {
  return /^[A-Za-z_$][\w$]*$/.test(name) ? name : JSON.stringify(name);
}

function componentTypeName(component, suffix) {
  return `${component.exportName}${suffix}`;
}

function elementType(component) {
  return `VyrnForgeElementForTagName<${JSON.stringify(component.tag)}>`;
}

function primitiveDetailType(type) {
  if (["string", "number", "boolean", "bigint", "void", "unknown"].includes(type)) {
    return type;
  }
  if (type === "boolean | mixed") return 'boolean | "mixed"';
  if (type === "ValidityState") return "ValidityState";
  if (type.endsWith("[]")) {
    const item = type.slice(0, -2);
    return ["string", "number", "boolean", "unknown"].includes(item)
      ? `${item}[]`
      : "unknown[]";
  }
  return "unknown";
}

function eventDetailType(event) {
  if (event.detailFields.length === 0) return "unknown";
  return `{ ${event.detailFields
    .map(
      (field) =>
        `${propertyName(field.name)}${field.required ? "" : "?"}: ${primitiveDetailType(field.type)};`,
    )
    .join(" ")} }`;
}

function serializeProps(component) {
  const element = elementType(component);
  const lines = component.properties.map(
    (property) =>
      `  readonly ${propertyName(property.public)}${property.required ? "" : "?"}: ${element}[${JSON.stringify(property.canonical)}];`,
  );
  return `export interface ${componentTypeName(component, "Props")} {\n${lines.join("\n")}\n}`;
}

function serializeEmits(component) {
  const signatures = [];
  if (component.vModel?.enabled) {
    const canonicalProperty = component.vModel.canonicalProperty;
    signatures.push(
      `  (event: ${JSON.stringify(component.vModel.publicEvent)}, value: ${elementType(component)}[${JSON.stringify(canonicalProperty)}]): void;`,
    );
  }
  for (const event of component.events) {
    signatures.push(
      `  (event: ${JSON.stringify(event.public)}, payload: ${eventDetailType(event)}): void;`,
    );
  }
  if (signatures.length === 0) signatures.push("  (event: never): void;");
  return `export interface ${componentTypeName(component, "Emits")} {\n${signatures.join("\n")}\n}`;
}

function serializeSlots(component) {
  const lines = component.slots.map(
    (slot) => `  readonly ${propertyName(slot.public)}?: () => VNode[];`,
  );
  return `export interface ${componentTypeName(component, "Slots")} {\n${lines.join("\n")}\n}`;
}

function serializeRef(component) {
  return `export interface ${componentTypeName(component, "Ref")} {\n  readonly element: ${elementType(component)} | null;\n}`;
}

function serializeComponent(component) {
  return [
    serializeProps(component),
    serializeEmits(component),
    serializeSlots(component),
    serializeRef(component),
    `export const ${component.exportName} = ${component.exportName}Runtime as unknown as VyrnForgeVueComponentType<${componentTypeName(component, "Props")}, ${componentTypeName(component, "Emits")}, ${componentTypeName(component, "Slots")}, ${componentTypeName(component, "Ref")}>;`,
  ].join("\n\n");
}

export function createVueTypeModel(generationModel) {
  const nativeById = new Map(
    generationModel.surfaces.native.components.map((record) => [record.id, record]),
  );
  const components = generationModel.surfaces.vue.components
    .filter((record) => ["current", "target"].includes(record.status))
    .map((record) => {
      const native = nativeById.get(record.id);
      assert(record.export, `${record.id}: Vue export is required`);
      assert(native?.tag, `${record.id}: canonical element tag is required`);
      return {
        id: record.id,
        exportName: record.export,
        tag: native.tag,
        properties: record.properties,
        events: record.events,
        slots: record.slots,
        vModel: record.adapter.vModel,
      };
    })
    .sort((left, right) => compareText(left.id, right.id));
  assert(components.length === 59, `expected 59 components, got ${components.length}`);
  return Object.freeze(components);
}

export function serializeVueTypedCatalog(components) {
  const runtimeImports = components
    .map(
      (component) =>
        `  ${component.exportName} as ${component.exportName}Runtime,`,
    )
    .join("\n");
  const blocks = components.map(serializeComponent).join("\n\n");
  return `${GENERATED_HEADER}
import type {
  AllowedComponentProps,
  ComponentCustomProps,
  VNode,
  VNodeProps,
} from "vue";
import type { VyrnForgeElementForTagName } from "@vyrnforge/ui-elements";
import {
${runtimeImports}
} from "./catalog.generated";

export type VyrnForgeVueComponentType<Props, Emits, Slots, Ref> = {
  new (): {
    $props: Props & VNodeProps & AllowedComponentProps & ComponentCustomProps;
    $emit: Emits;
    $slots: Slots;
  } & Ref;
};

${blocks}
`;
}

export function buildVueTypedCatalogArtifact({ root } = {}) {
  const contracts = loadCanonicalComponentContracts({ root });
  const model = createFrameworkGenerationModel(contracts);
  const components = createVueTypeModel(model);
  return Object.freeze({
    path: VUE_TYPED_CATALOG_ARTIFACT_PATH,
    sourceRecords: ["component:*", "framework:vue:*", "framework:native:*"],
    content: serializeVueTypedCatalog(components),
    components,
  });
}
